style.css:
/* Фон для всех сайтов */
html, body {
    background: url("https://i.pinimg.com/736x/75/cb/b1/75cbb1ec3895e810b3e6b07472567f08.jpg") center center / cover no-repeat fixed !important;
    height: 100% !important;
    margin: 0 !important;
}

/* Тёмный слой поверх фона для читаемости текста */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.6);
    z-index: 0;
}

/* Контент поверх фона */
* {
    position: relative;
    background-color: rgba(0,0,0,0.0) !important; /* убираем фон сайтов, чтобы фон был виден */
    color: #fff !important; /* делаем текст белым для контраста */
}

/* Для сайтов с карточками и блоками */
div, section, main, article, header, footer {
    background-color: rgba(0,0,0,0.2) !important;
    backdrop-filter: blur(4px);
    border-radius: 6px;
}
